const labels=['Identification','Circonstances','Justificatifs','Récapitulatif','Confirmation'];let step=0;const d={};const $=s=>document.querySelector(s);const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function nav(){ $('#steps').innerHTML=labels.map((x,i)=>`<li class="${i===step?'active':''}">${i+1}. ${x}</li>`).join('');$('#prev').disabled=step===0||step===4;$('#next').textContent=step===3?'Confirmer le dépôt':step===4?'Recommencer':'Continuer →';}function render(){nav();let s='';if(step===0)s=`<h2>1. Identification</h2><p class="hint">Identité et contrat entièrement fictifs.</p><label>Nom de démonstration<input id="name" value="${esc(d.name||'')}" autocomplete="off"></label><label>Référence du contrat<input id="contract" value="${esc(d.contract||'')}" placeholder="DEMO-0001"></label><p id="err"></p>`;if(step===1)s=`<h2>2. Circonstances du sinistre</h2><label>Date du sinistre<input type="date" id="date" value="${esc(d.date||'')}"></label><label>Adresse du sinistre<input id="address" value="${esc(d.address||'')}"></label><label>Circonstances<select id="cause"><option value="">Choisir</option><option>Dégât des eaux accidentel</option><option>Origine incertaine — revue requise</option></select></label><label>Description<textarea id="desc">${esc(d.desc||'')}</textarea></label><label>Estimation indicative (€)<input type="number" min="0" max="100000" id="amount" value="${esc(d.amount||'')}"></label><p id="err"></p>`;if(step===2)s=`<h2>3. Photos et justificatifs</h2><p>Formats JPG, PNG ou PDF; 10 Mo par fichier et 30 Mo cumulés (hypothèses fictives). Les fichiers restent dans cette page et ne sont pas envoyés.</p><label>Choisir des fichiers<input type="file" id="files" accept="image/jpeg,image/png,application/pdf" multiple></label><p id="filelist">${esc(d.files||'Aucun fichier')}</p><p class="hint">Vous pouvez poursuivre sans pièce dans cette démonstration.</p>`;if(step===3)s=`<h2>4. Récapitulatif</h2><p>Vérifiez les données avant dépôt.</p><div class="card">${Object.entries({Assuré:d.name,Contrat:d.contract,Date:d.date,Adresse:d.address,Circonstances:d.cause,Description:d.desc,Estimation:d.amount+' €',Pièces:d.files||'Aucune'}).map(([k,v])=>`<p><b>${k} :</b> ${esc(v)}</p>`).join('')}</div><p id="err"></p>`;if(step===4)s=`<h2>5. Dépôt confirmé</h2><p>Référence fictive: <b>${esc(d.ref)}</b></p><p>Statut: Déposé — simulation locale uniquement.</p><p>Aucun gestionnaire réel n’a reçu cette déclaration.</p>`;$('#screen').innerHTML=s;$('#next').hidden=step===4;$('#prev').hidden=step===4;bind();}function save(){['name','contract','date','address','cause','desc','amount'].forEach(k=>{let e=document.getElementById(k);if(e)d[k]=e.value});}function validate(){save();let m=[];if(step===0){if(!d.name)m.push('Saisissez un nom de démonstration.');if(!/^DEMO-\d{4}$/.test(d.contract||''))m.push('Référence attendue : DEMO-0001.');else if(d.contract==='DEMO-0002')m.push('Contrat de démonstration hors période : vérification humaine nécessaire.');else if(d.contract!=='DEMO-0001')m.push('Contrat fictif inconnu : vérification humaine nécessaire.');}if(step===1){if(!d.date||!d.address||!d.cause||!d.desc||d.amount==='')m.push('Complétez tous les champs requis.');if(d.date&&new Date(d.date)>new Date())m.push('La date ne peut pas être dans le futur.');if(d.date&&(Date.now()-new Date(d.date).getTime())>365*86400000)m.push('La fenêtre de 365 jours est une hypothèse de démonstration.');if(+d.amount<0||+d.amount>100000)m.push('Montant attendu entre 0 et 100 000 €.');}if(step===3){if(+d.amount>=5000)d.route='Expertise à étudier (seuil fictif).';else d.route='Qualification gestionnaire.';if(d.cause&&d.cause.startsWith('Origine'))d.route='Revue humaine nécessaire.';}return m;}function bind(){const f=$('#files');if(f)f.onchange=()=>{const xs=[...f.files];if(xs.some(x=>!['image/jpeg','image/png','application/pdf'].includes(x.type)||x.size>10*1024*1024)||xs.reduce((a,x)=>a+x.size,0)>30*1024*1024){$('#filelist').innerHTML='<span class="error">Fichier refusé: formats JPG, PNG, PDF; 10 Mo chacun et 30 Mo cumulés.</span>';d.files='';}else{d.files=xs.map(x=>x.name).join(', ');$('#filelist').textContent=d.files||'Aucun fichier';}}}$('#prev').onclick=()=>{save();step=Math.max(0,step-1);render()};$('#next').onclick=()=>{if(step===3){const m=validate();if(m.length){$('#err').innerHTML=`<p class="error">${m.map(esc).join('<br>')}</p>`;return}d.ref='DS-2026-'+String(Math.floor(Math.random()*900000)+100000);try{localStorage.setItem('decla-status',JSON.stringify({ref:d.ref,status:'Déposé'}))}catch{}step=4;render();return}const m=validate();if(m.length){$('#err').innerHTML=`<p class="error">${m.map(esc).join('<br>')}</p>`;return}step++;render()};render();
